package io.fireflysoftware.domain.accounting.web.openapi;
import static org.junit.jupiter.api.Assertions.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.dataformat.yaml.YAMLFactory;
import io.fireflysoftware.domain.accounting.core.posting.*;
import java.nio.file.*;
import java.time.Duration;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.context.ApplicationContext;
import org.springframework.test.context.ActiveProfiles;
import org.springframework.test.web.reactive.server.WebTestClient;
/** Actual full controller producer; no owner Main or financial business port acceptance. */
@ActiveProfiles("openapi-gen")
@SpringBootTest(classes=OpenApiGenApplication.class,webEnvironment=SpringBootTest.WebEnvironment.MOCK,properties={"spring.main.web-application-type=reactive","springdoc.api-docs.version=OPENAPI_3_0"})
class ManagedPostingProducerContractTest {
    static final String BASE="/api/v1/tenants/{tenantId}/books/{bookId}/ledger-journals";
    @Autowired ApplicationContext context;
    record Operation(String path,String verb,String id){}
    Set<Operation> operations(JsonNode doc){var values=new HashSet<Operation>();doc.path("paths").fields().forEachRemaining(path->path.getValue().fields().forEachRemaining(method->{if(Set.of("get","post","put","patch","delete","head","options","trace").contains(method.getKey()))assertTrue(values.add(new Operation(path.getKey(),method.getKey(),method.getValue().path("operationId").asText())));}));return values;}
    JsonNode actual()throws Exception{var client=WebTestClient.bindToApplicationContext(context).configureClient().responseTimeout(Duration.ofSeconds(3)).build();var json=client.get().uri("/v3/api-docs").exchange().expectStatus().isOk().expectBody().returnResult().getResponseBody();var yaml=client.get().uri("/v3/api-docs.yaml").exchange().expectStatus().isOk().expectBody().returnResult().getResponseBody();assertNotNull(json);assertNotNull(yaml);assertTrue(json.length>0&&json.length<=4194304&&yaml.length>0&&yaml.length<=4194304);var actual=new ObjectMapper().readTree(json);assertEquals(actual,new ObjectMapper(new YAMLFactory()).readTree(yaml));Files.createDirectories(Path.of("target/managed-posting-producer"));Files.write(Path.of("target/managed-posting-producer/openapi.json"),json);Files.write(Path.of("target/managed-posting-producer/openapi.yml"),yaml);return actual;}
    JsonNode resolve(JsonNode document,JsonNode value){return value.has("$ref")?document.at(value.path("$ref").asText().substring(1)):value;}
    @Test void allThreeOriginalOperationsSurviveAndOnlyTwoManagedOperationsAreAdded()throws Exception{var expected=Set.of(new Operation("/api/v1/journals","post","postJournal"),new Operation("/api/v1/journals/{businessDate}","get","readJournal"),new Operation("/api/v1/accounts/{id}","get","readAccount"),new Operation(BASE,"post","postLedgerJournal"),new Operation(BASE+"/recovery","post","recoverLedgerJournal"));assertEquals(expected,operations(actual()));}
    @Test void typedOriginalRequestAndRecoveryOutcomesKeepBearerAndDisableGenericReplay()throws Exception{var document=actual();for(var path:List.of(BASE,BASE+"/recovery")){var operation=document.path("paths").path(path).path("post");assertTrue(operation.path("security").toString().contains("accountingDomainBearer"));var input=resolve(document,operation.path("requestBody").path("content").path("application/json").path("schema"));assertEquals("object",input.path("type").asText());assertTrue(input.path("properties").has("expectedIntentDigest"));assertTrue(input.path("properties").has("posting"));for(var status:List.of("200","4XX")){var response=resolve(document,operation.path("responses").path(status).path("content").path("application/json").path("schema"));assertTrue(response.path("properties").has("actionId"));assertTrue(response.path("properties").has("intentDigest"));assertTrue(response.path("properties").has("status"));}for(var status:List.of("400","401","403","404","409","422","503")){var schema=operation.path("responses").path(status).path("content").path("application/json").path("schema");assertEquals(Set.of("#/components/schemas/ManagedPostingResponse","#/components/schemas/ManagedPostingPreDispatchError"),java.util.stream.StreamSupport.stream(schema.path("oneOf").spliterator(),false).map(value->value.path("$ref").asText()).collect(java.util.stream.Collectors.toSet()));}var pre=resolve(document,document.path("components").path("schemas").path("ManagedPostingPreDispatchError"));assertTrue(pre.path("properties").has("phase"));assertTrue(pre.path("properties").has("code"));assertFalse(pre.path("properties").has("actionId"));assertTrue(operation.path("responses").has("default"));for(var parameter:operation.path("parameters"))assertFalse(parameter.path("name").asText().equalsIgnoreCase("X-Idempotency-Key"));}}
    @Test void receiptHasNamedInstantAndProducerCreatesNoBusinessClientOrStore()throws Exception{var document=actual();assertEquals("#/components/schemas/FireflyInstant",document.path("components").path("schemas").path("ManagedPostingReceipt").path("properties").path("recordedAt").path("$ref").asText());assertEquals("string",document.path("components").path("schemas").path("FireflyInstant").path("type").asText());assertEquals(0,context.getBeanNamesForType(ManagedPostingClientFactory.class,false,false).length);assertEquals(0,context.getBeanNamesForType(ManagedPostingExecution.class,false,false).length);}
    @Test void completeActualProducerBecomesTheSdkInputOnlyAfterAllContractAssertions()throws Exception{allThreeOriginalOperationsSurviveAndOnlyTwoManagedOperationsAreAdded();typedOriginalRequestAndRecoveryOutcomesKeepBearerAndDisableGenericReplay();receiptHasNamedInstantAndProducerCreatesNoBusinessClientOrStore();io.fireflysoftware.domain.accounting.web.openapi.impl.OriginalProducerSdkInputFixtureImpl.writeIfRequested(Files.readAllBytes(Path.of("target/managed-posting-producer/openapi.yml")));}
}
